// 判断是否为运算符
int isOperator(string c) {
    return c == "+" || c == "-" || c == "*";
}
​
// 使用栈处理表达式计算
int calc(vector<string>& express) {
    // 操作符栈
    stack<string>  operatorStack;
    // 操作数栈
    stack<int> numberStack;
    int n = express.size(); 
    for (int i = 0; i < n; i++) {
        if (isOperator(express[i])) {
            if (operatorStack.empty()) {
                operatorStack.push(express[i]);
            } else {
                // 当前操作符优先级小于上一个,上一个应该可以直接进行运行
                while ((express[i] == "+" || express[i] == "-") && !operatorStack.empty() && operatorStack.top() == "*") {
                    int number2 = numberStack.top();numberStack.pop();
                    int number1 = numberStack.top();numberStack.pop();
                    operatorStack.pop();
                    int res = number1 * number2;
                    numberStack.push(res);
                }
                operatorStack.push(express[i]);
            }
        } else {
            numberStack.push(stoi(express[i]));
        }
    }

    while (!operatorStack.empty()) {
        string operat = operatorStack.top();
        operatorStack.pop();
        int number2 = numberStack.top();numberStack.pop();
        int number1 = numberStack.top();numberStack.pop();
        int res = 0;
        if (operat == "+") {
            res = number1 + number2;
        } else if (operat == "-"){
            res = number1 - number2;
        } else {
            res = number1 * number2;
        }
        numberStack.push(res);
    }
    int res = numberStack.top();
    return res;
}
