            start = end + 1;
            continue;
        }
        // 存储合法的表达式片段
        stack<string> stk;
        while (end < n) {
            string tmp = "";
            if (isdigit(input[end])) {
                // 获取连续数字字符
                tmp.push_back(input[end]);
                // 贪婪的一次获取所有的数字
                while (end + 1< n && isdigit(input[end + 1])) {
                    end += 1;
                    tmp.push_back(input[end]);
                }
            } else if (input[end] == '*' || input[end] == '+' || input[end] == '-') {   
                tmp.push_back(input[end]);
            } else {
                break;
            }
            // 判断是否合法

            // 当前字符串是运算符,前一个必须为数字
            if (isOperator(tmp)) {
                if (stk.empty()) {
                    break;
                }
                string top = stk.top();
                // 不能连续出现两个运算符
                if (isOperator(top)) {
                    break;
                } 
                stk.push(tmp);
            // 当前为数字 栈为空或者前一个是运算符
            } else {
                if (stk.empty() || isOperator(stk.top())) {
                    stk.push(tmp);
                } else {
                    break;
                }
            }
            end++;
        }

        // 栈中如果最后为运算符直接移除
        if (!stk.empty() && isOperator(stk.top())) {
            stk.pop();
        }

