            while (!stk.empty()) {
                string top = stk.top();
                stk.pop();
                currentLen += top.size();
                tmp.push_back(top);
            }
            // 当前表达式大于之前表达式长度时
            if (currentLen > maxLen) {
                // 反转一下,
                reverse(tmp.begin(), tmp.end());
                res = tmp;
                maxLen = currentLen;
            }
        }
        start = end + 1;
    }
​

