public class Main {
    // 判断是否为运算符
    static boolean isOperator(String c) {
        return c.equals("+") || c.equals("-") || c.equals("*");
    }
​
    // 使用栈处理表达式计算
    static int calc(List<String> express) {
        // 操作符栈
        Stack<String> operatorStack = new Stack<>();
        // 操作数栈
        Stack<Integer> numberStack = new Stack<>();
​
        for (String token : express) {
            if (isOperator(token)) {
                if (operatorStack.isEmpty()) {
                    operatorStack.push(token);
                } else {
                    // 当前操作符优先级小于上一个，上一个应该可以直接进行运行
                    while ((token.equals("+") || token.equals("-")) &&
                            !operatorStack.isEmpty() && operatorStack.peek().equals("*")) {
                        int number2 = numberStack.pop();
                        int number1 = numberStack.pop();
                        operatorStack.pop();
                        numberStack.push(number1 * number2);
                    }
                    operatorStack.push(token);
                }
            } else {
                numberStack.push(Integer.parseInt(token));
            }
        }
​

        while (!operatorStack.isEmpty()) {
            String op = operatorStack.pop();
            int number2 = numberStack.pop();
            int number1 = numberStack.pop();
            int res = 0;
            if (op.equals("+")) res = number1 + number2;
            else if (op.equals("-")) res = number1 - number2;
            else res = number1 * number2;
            numberStack.push(res);
        }
​
        return numberStack.pop();
    }
