import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 判断是否为运算符
func isOperator(c string) bool {
    return c == "+" || c == "-" || c == "*"
}
​
// 使用栈处理表达式计算
func calc(express []string) int {
    // 操作符栈
    operatorStack := []string{}
    // 操作数栈
    numberStack := []int{}
​
    for _, token := range express {
        if isOperator(token) {
            if len(operatorStack) == 0 {
                operatorStack = append(operatorStack, token)
            } else {
                // 当前操作符优先级小于上一个, 上一个应该可以直接进行运算
                for (token == "+" || token == "-") && len(operatorStack) > 0 && operatorStack[len(operatorStack)-1] == "*" {
                    n2 := numberStack[len(numberStack)-1]
                    numberStack = numberStack[:len(numberStack)-1]
                    n1 := numberStack[len(numberStack)-1]
                    numberStack = numberStack[:len(numberStack)-1]
                    operatorStack = operatorStack[:len(operatorStack)-1]
                    numberStack = append(numberStack, n1*n2)
                }
                operatorStack = append(operatorStack, token)
            }
        } else {
            val, _ := strconv.Atoi(token)
            numberStack = append(numberStack, val)
        }
    }
​

    for len(operatorStack) > 0 {
        oper := operatorStack[len(operatorStack)-1]
        operatorStack = operatorStack[:len(operatorStack)-1]
        n2 := numberStack[len(numberStack)-1]
        numberStack = numberStack[:len(numberStack)-1]
        n1 := numberStack[len(numberStack)-1]
        numberStack = numberStack[:len(numberStack)-1]
        res := 0
        if oper == "+" {
            res = n1 + n2
        } else if oper == "-" {
            res = n1 - n2
        } else {
            res = n1 * n2
        }
        numberStack = append(numberStack, res)
    }
    return numberStack[0]
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    input, _ := reader.ReadString('\n')
    input = strings.TrimSpace(input)
    n := len(input)
    start := 0
    res := []string{}
    maxLen := 0
​
    for start < n {
        end := start
        // 表达式以数字开始
        if !('0' <= input[end] && input[end] <= '9') {
            start = end + 1
            continue
        }
        // 存储合法的表达式片段
        stk := []string{}
        for end < n {
            tmp := ""
            if '0' <= input[end] && input[end] <= '9' {
                tmp += string(input[end])
                for end+1 < n && '0' <= input[end+1] && input[end+1] <= '9' {
                    end++
                    tmp += string(input[end])
                }
            } else if input[end] == '*' || input[end] == '+' || input[end] == '-' {
                tmp += string(input[end])
            } else {
                break
            }
            // 判断是否合法
            if isOperator(tmp) {
                if len(stk) == 0 {
                    break
                }
                top := stk[len(stk)-1]
                if isOperator(top) {
                    break
                }
                stk = append(stk, tmp)
            } else {
                if len(stk) == 0 || isOperator(stk[len(stk)-1]) {
                    stk = append(stk, tmp)
                } else {
                    break
                }
            }
            end++
        }
​
        // 栈中如果最后为运算符直接移除
        if len(stk) > 0 && isOperator(stk[len(stk)-1]) {
            stk = stk[:len(stk)-1]
        }
​
        // 大于3个这样才会构成一个合法的表达式
        if len(stk) >= 3 {
            tmp := []string{}
            currentLen := 0
            for i := len(stk) - 1; i >= 0; i-- {
                top := stk[i]
                currentLen += len(top)
                tmp = append(tmp, top)
            }
            if currentLen > maxLen {
                // 反转
                for i, j := 0, len(tmp)-1; i < j; i, j = i+1, j-1 {
                    tmp[i], tmp[j] = tmp[j], tmp[i]
                }
                res = tmp
                maxLen = currentLen
            }
        }
        start = end + 1
    }
​
    // 没有合法表达式
    if maxLen == 0 {
        fmt.Println(0)
    } else {
        // 计算值
        result := calc(res)
        fmt.Println(result)
    }
}
